// @ts-nocheck
// ===== หาว่าคีย์เลขรุ่นบน HMI แล้วไปเปลี่ยนที่ D ไหน (อ่านอย่างเดียว) =====
// 1) กด "① จำค่าก่อน"  2) ไปคีย์เลขบนจอ HMI (เช่น 2) แล้วกด ENT  3) กด "② เทียบหลังคีย์"
const HOST = "192.168.250.1", DA1 = 1, SA1 = 50;     // SA1 = เลขท้าย IP กล่อง
const AREAS = [["D", 0x82, 0, 2999], ["W", 0xB1, 0, 511], ["H", 0xB2, 0, 511]];
const CHUNK = 200;
const SKIP = d => d.startsWith("D") && +d.slice(1) >= 540 && +d.slice(1) <= 579;   // ข้ามช่วงเครื่องชั่ง (ค่าวิ่งตลอด)

if (context.get("busy")) return null;
context.set("busy", true);
const mode = msg.payload === "compare" ? "compare" : "snap";
const sock = dgram.createSocket("udp4");
let sid = 0, pending = null;
sock.on("message", r => { if (pending && r.length >= 14 && r[9] === sid) pending(null, r); });
sock.on("error", e => pending && pending("socket " + e.code));
function read(area, start, count) {
    return new Promise(res => {
        sid = (sid + 1) & 0xFF;
        const t = setTimeout(() => pending && pending("timeout"), 1200);
        pending = (err, r) => {
            clearTimeout(t); pending = null;
            if (err) return res({ err });
            const ec = r.readUInt16BE(12);
            if (ec !== 0 && ec !== 0x0040) return res({ err: "end code 0x" + ec.toString(16) });
            const w = []; for (let k = 0; k < count; k++) w.push(r.readUInt16BE(14 + k * 2));
            res({ w });
        };
        sock.send(Buffer.from([0x80, 0, 0x02, 0, DA1, 0, 0, SA1, 0, sid, 0x01, 0x01, area,
            (start >> 8) & 0xFF, start & 0xFF, 0, (count >> 8) & 0xFF, count & 0xFF]), 9600, HOST, e => { if (e && pending) pending("send " + e.code); });
    });
}
const ch = c => (c >= 32 && c < 127 ? String.fromCharCode(c) : "·");
const sw = w => ch(w & 0xFF) + ch((w >> 8) & 0xFF);      // แบบ NJ (สลับ byte)
const nm = w => ch((w >> 8) & 0xFF) + ch(w & 0xFF);      // แบบปกติ

(async () => {
    sock.bind(0);
    const mem = {}, errs = [];
    for (const [name, code, from, to] of AREAS) {
        for (let s = from; s <= to; s += CHUNK) {
            const n = Math.min(CHUNK, to - s + 1);
            node.status({ fill: "blue", shape: "dot", text: "กำลังอ่าน " + name + s + "…" });
            const r = await read(code, s, n);
            if (r.err) { errs.push(name + s + ": " + r.err); continue; }
            r.w.forEach((v, k) => mem[name + (s + k)] = v);
        }
    }
    try { sock.close(); } catch (e) {}
    context.set("busy", false);
    if (mode === "snap") {
        flow.set("hmi_snap", mem);
        node.status({ fill: "green", shape: "dot", text: "จำค่าแล้ว " + Object.keys(mem).length + " word · ไปคีย์เลขบน HMI แล้วกด ②" });
        node.send({ payload: { "ขั้นต่อไป": "คีย์เลขรุ่นบนจอ HMI แล้วกด ENT จากนั้นกด ② เทียบหลังคีย์", "อ่านไม่ได้": errs.length ? errs : undefined } });
        return;
    }
    const old = flow.get("hmi_snap");
    if (!old) { node.status({ fill: "yellow", shape: "ring", text: "ยังไม่ได้กด ① ก่อน" }); return; }
    const changes = [];
    for (const k of Object.keys(mem)) {
        if (old[k] === undefined || old[k] === mem[k] || SKIP(k)) continue;
        const a = old[k], b = mem[k];
        changes.push({ "ที่อยู่": k, "ก่อน": a + " (0x" + a.toString(16).padStart(4, "0") + ") \"" + sw(a) + "\"", "หลัง": b + " (0x" + b.toString(16).padStart(4, "0") + ") \"" + sw(b) + "\" / ปกติ \"" + nm(b) + "\"" });
    }
    node.status({ fill: changes.length ? "green" : "yellow", shape: "dot", text: "เปลี่ยน " + changes.length + " ตำแหน่ง" });
    node.send({ payload: { "จำนวนที่เปลี่ยน": changes.length, "ตำแหน่งที่เปลี่ยน": changes.slice(0, 100), "อ่านไม่ได้": errs.length ? errs : undefined } });
})();
return null;
